import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { signAttributesHandler } from "../handlers/signAttributesHandler";
import type { ApiError } from "../runtime/client";
import type { SignAttributesRequest } from "../types/SignAttributesRequest";

type Data = Awaited<ReturnType<typeof signAttributesHandler>>;
type Vars = SignAttributesRequest;

export function useSignAttributes(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => signAttributesHandler(vars),
    ...options,
  });
}
